\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}

	\pagestyle{empty} %% IMPORTANT

	\begin{tikzpicture}[scale = 1.0]
	\def\gcolor{deepskyblue}
	\def\acolor{black}

	\begin{axis}[
	trig format plots=rad,
	legend pos=outer north east,
	tick label style={font=\footnotesize},
	tick style={line width=0.8pt, color=black},
	label style={font=\small},
	legend style={font=\footnotesize},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	xmin = -1.5,
	xmax = 1.5,
	ymin = -1.9,
	ymax = 1.9,
	xtick={-1, 1},
	ytick = {-1.57, 1.57}, 
	yticklabels={$\displaystyle-\frac\pi 2$, $\displaystyle\frac\pi 2$},
	xlabel = $x$,
	ylabel = {$y$},
	every axis x label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=west,
	},
	every axis y label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=south,
	},
	]

	\addplot [
	domain = 0:1,
	samples=200,
	color=\gcolor,
	line width=1.2pt,
	]{asin(2*x-1)};

	\draw [color=\acolor, line width=1.2pt, dotted, opacity=0.5] (axis cs:1, 1.57) -- (axis cs:0, 1.57);

%	\draw [color=\acolor, line width=1.2pt, dotted, opacity=0.5] (axis cs:-1, -1.57) -- (axis cs:-0.35, -1.57);

	\end{axis}
	\end{tikzpicture}
\end{document}

